const usersForSignIn = `-- name: UsersForSignIn :many
select u.id, u.username, u.email, u.email_verified_at, u.password_hash,
       u.role,
       exists (
           select 1 from oauth_identities oi
            where oi.user_id = u.id and oi.provider = 'discord'
       ) as discord_linked
  from users u
 where u.email = $1 and u.password_hash is not null
`

type UsersForSignInRow struct {
	ID              pgtype.UUID
	Username        string
	Email           pgtype.Text
	EmailVerifiedAt pgtype.Timestamptz
	PasswordHash    pgtype.Text
	Role            string
	DiscordLinked   bool
}

func (q *Queries) UsersForSignIn(ctx context.Context, email pgtype.Text) ([]UsersForSignInRow, error) {
	rows, err := q.db.Query(ctx, usersForSignIn, email)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	var items []UsersForSignInRow
	for rows.Next() {
		var i UsersForSignInRow
		if err := rows.Scan(
			&i.ID,
			&i.Username,
			&i.Email,
			&i.EmailVerifiedAt,
			&i.PasswordHash,
			&i.Role,
			&i.DiscordLinked,
		); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

